import type { HardwareState } from './engine';

/** Serial frames generated by the model; no physical serial port or firmware ACK is implied. */
export function actuatorCommand(s: HardwareState): string {
  if (!s.started || s.fault === 'estop' || s.fault === 'power') return 'STOP\n';
  let mask = 0;
  s.relayDry.forEach((on, i) => { if (on) mask |= 1 << i; });
  s.relayWet.forEach((on, i) => { if (on) mask |= 1 << (i + 4); });
  if (s.pump) mask |= 1 << 8;
  if (s.motor) mask |= 1 << 9;
  if (s.windFan) mask |= 1 << 10;
  return `SET ${mask}\n`;
}
export function sensorFrame(s: HardwareState): string {
  return JSON.stringify({ source: 'virtual-esp32-1', second: s.second, link: ['sensor', 'power'].includes(s.fault) ? 'FAULT' : 'OK', pm25: s.inputs.pm25, pm10: s.inputs.pm10, windToward: s.inputs.windDirection, windMps: s.inputs.windSpeed, temperatureC: s.inputs.temperatureC, humidity: s.inputs.humidity, flowLpm: s.flowLpm, pressureBar: s.pressureBar, hepaPa: s.hepaPa });
}
